// Combine SerpAPI results into context for Claude
const trendsData = $('HTTP: SerpAPI — Trending Topics').item.json;
const newsData = $('HTTP: SerpAPI — Local News Headlines').item.json;

// Extract trending topics
let trendingTopics = [];
if (trendsData.interest_over_time && trendsData.interest_over_time.timeline_data) {
  trendingTopics = trendsData.interest_over_time.timeline_data
    .slice(0, 5)
    .map(d => d.values ? d.values[0]?.query : 'Local events')
    .filter(Boolean);
}
if (!trendingTopics.length) trendingTopics = ['Long Island summer events', 'Nassau County community', 'Local gift ideas'];

// Extract local news snippets
let newsSnippets = [];
if (newsData.organic_results) {
  newsSnippets = newsData.organic_results
    .slice(0, 3)
    .map(r => r.snippet || r.title)
    .filter(Boolean);
}

// Build today's context
const today = new Date();
const dateStr = today.toLocaleDateString('en-US', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });

// Seasonal/occasion context
const month = today.getMonth(); // 0-11
const occasions = {
  0: 'New Year celebrations, Valentine Day prep',
  1: 'Valentine Day, Presidents Day',
  2: 'St Patricks Day, Spring events, Mardi Gras',
  3: 'Easter, Passover, Spring cleaning',
  4: "Mother's Day, Graduations, Memorial Day",
  5: "Father's Day, Graduations, Summer starts",
  6: 'Fourth of July, Summer BBQs, Back to school prep',
  7: 'Back to school, Late summer events',
  8: 'Labor Day, Fall begins, Rosh Hashanah, Yom Kippur',
  9: 'Halloween, Columbus Day, Breast Cancer Awareness',
  10: 'Thanksgiving, Veterans Day, Holiday shopping starts',
  11: 'Christmas, Hanukkah, New Year prep, Holiday gifts',
};

const context = {
  date: dateStr,
  trending: trendingTopics,
  news: newsSnippets,
  season_occasion: occasions[month],
};

return [{ json: context }];

