// Parse Claude's JSON response
const response = $input.first().json;
let blogData;

try {
  const content = response.content[0].text;
  // Remove any accidental markdown code fences
  const cleaned = content.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  blogData = JSON.parse(cleaned);
} catch(e) {
  // Fallback if Claude didn't return valid JSON
  blogData = {
    title: 'Your Long Island One-Stop Shop — News & Updates',
    slug: 'long-island-convenience-update-' + Date.now(),
    meta_description: 'Visit Long Island Convenience in Plainview NY for gift baskets, balloons, sports cards, printing and more.',
    tags: ['Long Island', 'Plainview NY', 'Nassau County'],
    html_body: '<h2>Visit Us Today</h2><p>Stop by Long Island Convenience at 605 Old Country Road, Plainview NY 11803.</p>',
    social_caption: '🏪 Something exciting is happening at Long Island Convenience! Visit us in Plainview NY. #LongIsland #PlainviewNY',
    hashtags: ['LongIsland', 'PlainviewNY', 'NassauCounty'],
  };
}

return [{ json: blogData }];

// Merge blog data with the generated image URL
const blogData = $('Code: Parse Claude Response').item.json;
const imageData = $('HTTP: DALL-E 3 — Blog Featured Image').item.json;

const imageUrl = imageData?.data?.[0]?.url || null;

// Build Odoo JSON-RPC payload for blog.post creation
const today = new Date();
const blogPayload = {
  // Blog data
  blog_data: blogData,
  image_url: imageUrl,
  // Odoo model fields
  odoo_fields: {
    name: blogData.title,
    subtitle: blogData.meta_description,
    content: blogData.html_body,
    website_published: true,
    is_published: true,
    website_id: 1,           // WID=1 — LongIslandConvenience.com
    blog_id: 6,              // Blog ID=6 =

 on WID=1 LIC
    tag_ids: [],             // We'll add tags separately
    website_meta_title: blogData.title + ' | Long Island Convenience',
    website_meta_description: blogData.meta_description,
    website_meta_keywords: blogData.tags.join(', '),
  },
  // For social sharing via WF-A
  social_payload: {
    brand: 'longislandconvenience',
    content_type: 'blog',
    text: blogData.social_caption,
    text_long: blogData.social_caption,
    image_url: imageUrl,
    link_url: 'https://www.longislandconvenience.com/blog/' + blogData.slug,
    hashtags: blogData.hashtags,
    platforms: ['facebook', 'instagram', 'pinterest', 'twitter'],
  },
};

return [{ json: blogPayload }];

// Log the result
const blogPost = $('Code: Build Odoo + Social Payload').item.json;
const odooResult = $('HTTP: Odoo — Create Blog Post').item.json;
const socialResult = $('HTTP: Trigger WF-A Social Blast').item.json;

console.log('=== WF-B Daily Blog Complete ===');
console.log('Blog title:', blogPost.blog_data.title);
console.log('Odoo post ID:', odooResult.result);
console.log('Social blast result:', JSON.stringify(socialResult));

return [{
  json: {
    success: true,
    title: blogPost.blog_data.title,
    odoo_post_id: odooResult.result,
    image_url: blogPost.image_url,
    social_blast_status: socialResult.status,
    timestamp: new Date().toISOString(),
  }
}];
